// Query the project name and validate basic invariants without taking ownership.
const char *name = lime_project_name();
// The API states the pointer is read-only and not owned by the caller; ensure it is usable.
if (!name) { FUZZ_BAIL(); }
// Validate it looks like a C string by searching for a NUL terminator with a hard cap to avoid runaway reads.
size_t max_scan = 4096; // keep bounded per fuzzer performance guidance
size_t len = 0;
for (; len < max_scan; ++len) {
    if (name[len] == '\0') { break; }
}
if (len == max_scan) { FUZZ_BAIL(); }
// Do not modify or free the pointer; no outputs are produced since the lifetime is library-owned/unspecified.
// Validation: Ensures non-null pointer and bounded NUL-terminated string; avoids ownership violations.

// lime_magic() should behave like a build-constant identifier; exercise and assert stability across calls.
unsigned int m1 = lime_magic();
unsigned int m2 = lime_magic();
FUZZ_ASSERT(m1 == m2, "lime_magic should be constant across calls");
// No owned objects are created; nothing to output.
// Validation: Asserts idempotence/constancy; no ownership or error paths to manage.

